    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 22-year-old develops urticaria, wheezing, and hypotension within minutes of peanut ingestion. Which immunologic mechanism is most directly responsible?', '["IgG-mediated complement activation", "Antigen cross-linking of IgE bound to mast cells", "Immune complex deposition in tissues", "CD8+ T-cell cytotoxicity", "Autoantibody-mediated receptor stimulation"]'::jsonb, 1, 'Type I hypersensitivity involves antigen cross-linking of IgE on mast cells, leading to immediate degranulation.'),
    (v_topic_id, 'Which cytokine is most important for class switching to IgE?', '["IL-2", "IL-4", "IFN-gamma", "IL-17", "TNF-alpha"]'::jsonb, 1, 'IL-4 and IL-13 are the primary cytokines that drive B-cell class switching to IgE.'),
    (v_topic_id, 'Late-phase allergic asthma is most strongly associated with infiltration by:', '["Neutrophils", "Eosinophils", "Basophils", "Plasma cells", "CD8+ T cells"]'::jsonb, 1, 'Eosinophils are recruited during the late phase of Type I hypersensitivity, often mediated by IL-5.'),
    (v_topic_id, 'A patient develops hemolytic anemia after penicillin therapy. Direct Coombs test is positive. This is an example of:', '["Type I hypersensitivity", "Type II hypersensitivity", "Type III hypersensitivity", "Type IV hypersensitivity", "Immune deficiency"]'::jsonb, 1, 'Drug-induced hemolytic anemia is a classic Type II hypersensitivity where antibodies target antigens on cell surfaces.'),
    (v_topic_id, 'Goodpasture syndrome is caused by antibodies directed against:', '["Desmoglein", "TSH receptor", "Type IV collagen", "dsDNA", "Myelin basic protein"]'::jsonb, 2, 'Goodpasture syndrome involves anti-GBM antibodies targeting the alpha-3 chain of Type IV collagen.'),
    (v_topic_id, 'A woman with Graves disease has heat intolerance and exophthalmos. The mechanism is:', '["IgE-mediated mast cell degranulation", "Immune complex deposition", "Stimulating IgG autoantibodies against TSH receptor", "Delayed T-cell injury", "Complement deficiency"]'::jsonb, 2, 'Graves disease is caused by thyroid-stimulating immunoglobulins (TSI) that act as agonists at the TSH receptor.'),
    (v_topic_id, 'Which disease is caused by antibody-mediated blockade of receptors rather than destruction?', '["Autoimmune hemolytic anemia", "Goodpasture syndrome", "Myasthenia gravis", "Pemphigus vulgaris", "Rheumatic fever"]'::jsonb, 2, 'In Myasthenia Gravis, antibodies block or internalize acetylcholine receptors at the NMJ.'),
    (v_topic_id, 'Serum sickness is best classified as:', '["Type I hypersensitivity", "Type II hypersensitivity", "Type III hypersensitivity", "Type IV hypersensitivity", "Complement deficiency"]'::jsonb, 2, 'Serum sickness is a systemic Type III hypersensitivity caused by circulating immune complexes.'),
    (v_topic_id, 'Poststreptococcal glomerulonephritis is primarily caused by:', '["Anti-GBM antibodies", "Immune complex deposition", "IgE-mediated inflammation", "CD8+ T-cell injury", "Complement absence"]'::jsonb, 1, 'PSGN is a Type III hypersensitivity where immune complexes deposit in the glomerular basement membrane.'),
    (v_topic_id, 'Which immunofluorescence pattern is typical of poststreptococcal glomerulonephritis?', '["Linear", "Granular", "Negative", "Nuclear only", "Membranous smooth staining"]'::jsonb, 1, 'A granular "lumpy-bumpy" pattern on IF indicates the deposition of immune complexes.'),
    (v_topic_id, 'A patient develops contact dermatitis 48 hours after nickel exposure. This is:', '["Type I hypersensitivity", "Type II hypersensitivity", "Type III hypersensitivity", "Type IV hypersensitivity", "Type V hypersensitivity"]'::jsonb, 3, 'Contact dermatitis is a delayed-type (Type IV) cell-mediated hypersensitivity.'),
    (v_topic_id, 'The PPD skin test is mediated primarily by:', '["IgE and eosinophils", "IgG and complement", "Th1 cells and macrophages", "Immune complexes", "Mast cells"]'::jsonb, 2, 'The tuberculin skin test relies on Th1 cells and macrophage activation (Type IV).'),
    (v_topic_id, 'Which cytokine is most important for macrophage activation in type IV hypersensitivity?', '["IL-4", "IL-5", "IFN-gamma", "IL-10", "TGF-beta"]'::jsonb, 2, 'Interferon-gamma (IFN-g) is the primary activator of macrophages.'),
    (v_topic_id, 'A child has recurrent infections with catalase-positive organisms. Nitroblue tetrazolium test is abnormal. Diagnosis?', '["LAD", "CGD", "Chediak-Higashi", "SCID", "DiGeorge syndrome"]'::jsonb, 1, 'Chronic Granulomatous Disease (CGD) involves defective NADPH oxidase, leading to failure of the oxidative burst.'),
    (v_topic_id, 'The defect in chronic granulomatous disease is:', '["CD18 deficiency", "NADPH oxidase deficiency", "MPO deficiency", "BTK mutation", "ADA deficiency"]'::jsonb, 1, 'CGD is caused by mutations in the NADPH oxidase complex.'),
    (v_topic_id, 'Delayed separation of the umbilical cord and absent pus suggest:', '["Chediak-Higashi syndrome", "Leukocyte adhesion deficiency", "Bruton''s agammaglobulinemia", "Hyper-IgM syndrome", "Selective IgA deficiency"]'::jsonb, 1, 'LAD type 1 involves a defect in CD18, preventing neutrophil migration and leading to delayed cord separation.'),
    (v_topic_id, 'Which molecule is deficient in leukocyte adhesion deficiency?', '["CD3", "CD18", "CD40L", "BTK", "C3"]'::jsonb, 1, 'The classic defect in LAD type 1 is the beta-2 integrin subunit (CD18).'),
    (v_topic_id, 'A child has recurrent sinopulmonary infections after 6 months of age, absent mature B cells, and low immunoglobulins. Diagnosis?', '["CVID", "Bruton''s agammaglobulinemia", "Selective IgA deficiency", "Hyper-IgM syndrome", "SCID"]'::jsonb, 1, 'Bruton''s (X-linked) agammaglobulinemia presents with a total lack of mature B cells and pan-hypogammaglobulinemia.'),
    (v_topic_id, 'Bruton''s agammaglobulinemia is caused by mutation in:', '["BTK", "CD40L", "WAS", "ATM", "ADA"]'::jsonb, 0, 'Bruton tyrosine kinase (BTK) is essential for B-cell maturation.'),
    (v_topic_id, 'Why do symptoms of Bruton''s agammaglobulinemia begin after 6 months?', '["Complement becomes deficient", "Maternal IgG protection declines", "IgA production stops", "T cells disappear", "Bone marrow fails"]'::jsonb, 1, 'Passively acquired maternal IgG provides protection for the first few months of life.'),
    (v_topic_id, 'Selective IgA deficiency predisposes to:', '["Neisseria meningitis", "Giardia infections", "PCP pneumonia", "Aspergillosis", "Toxoplasmosis"]'::jsonb, 1, 'Lack of mucosal IgA increases susceptibility to Giardia lamblia.'),
    (v_topic_id, 'Patients with selective IgA deficiency are at risk for:', '["Hemolytic anemia after transfusion", "Anaphylaxis after transfusion", "Delayed graft rejection", "Hyperacute rejection", "Severe neutropenia"]'::jsonb, 1, 'Patients can develop anti-IgA antibodies, leading to anaphylaxis when receiving blood products containing IgA.'),
    (v_topic_id, 'Hyper-IgM syndrome results from:', '["BTK mutation", "Failure of class switching due to CD40L deficiency", "Absence of thymus", "C3 deficiency", "Defective oxidative burst"]'::jsonb, 1, 'Defective CD40L on T cells prevents the "second signal" required for B-cell class switching.'),
    (v_topic_id, 'Which infection is classically associated with Hyper-IgM syndrome?', '["Pneumocystis jirovecii", "Neisseria meningitidis", "Giardia lamblia", "EBV only", "Influenza"]'::jsonb, 0, 'CD40L deficiency also impairs macrophage activation, increasing risk for PCP.'),
    (v_topic_id, 'An infant has chronic diarrhea, thrush, recurrent infections, and failure to thrive. Diagnosis?', '["DiGeorge syndrome", "SCID", "CVID", "Bruton''s disease", "IgA deficiency"]'::jsonb, 1, 'Severe Combined Immunodeficiency (SCID) affects both T and B cell function.'),
    (v_topic_id, 'A cause of SCID is:', '["ADA deficiency", "C3 deficiency", "CD18 deficiency", "Factor H deficiency", "C1 inhibitor deficiency"]'::jsonb, 0, 'Adenosine deaminase (ADA) deficiency is a major autosomal recessive cause of SCID.'),
    (v_topic_id, 'Definitive treatment for SCID is:', '["Steroids", "IVIG only", "Bone marrow transplant", "Splenectomy", "Thymectomy"]'::jsonb, 2, 'Hematopoietic stem cell transplant is the definitive curative treatment.'),
    (v_topic_id, 'Absent thymic shadow, hypocalcemia, and congenital heart disease indicate:', '["DiGeorge syndrome", "Hyper-IgM syndrome", "Wiskott-Aldrich syndrome", "CGD", "LAD"]'::jsonb, 0, 'DiGeorge syndrome involves a 22q11 deletion and failure of 3rd/4th pharyngeal pouch development.'),
    (v_topic_id, 'DiGeorge syndrome results from failure of development of:', '["1st pharyngeal pouch", "2nd pharyngeal pouch", "3rd and fourth pharyngeal pouches", "Neural tube", "Somites"]'::jsonb, 2, 'The 3rd and 4th pouches form the thymus and parathyroids.'),
    (v_topic_id, 'The primary immune defect in DiGeorge syndrome is:', '["B-cell deficiency", "T-cell deficiency", "Complement deficiency", "Neutrophil dysfunction", "IgA deficiency"]'::jsonb, 1, 'Thymic aplasia leads to a profound lack of mature T cells.'),
    (v_topic_id, 'Eczema, thrombocytopenia, recurrent infections, and small platelets suggest:', '["Job syndrome", "Wiskott-Aldrich syndrome", "Chediak-Higashi", "LAD", "SCID"]'::jsonb, 1, 'Wiskott-Aldrich Syndrome (WAS) is characterized by the triad of eczema, microthrombocytopenia, and infections.'),
    (v_topic_id, 'Wiskott-Aldrich syndrome classically shows:', '["Increased IgA and IgE, low IgM", "High IgM only", "Low IgA only", "No immunoglobulins", "Increased IgG only"]'::jsonb, 0, 'WAS typically shows elevated IgA/IgE with low IgM.'),
    (v_topic_id, 'Retained primary teeth, cold abscesses, eczema, and high IgE indicate:', '["LAD", "Job syndrome", "CGD", "DiGeorge syndrome", "Bruton''s disease"]'::jsonb, 1, 'Job Syndrome (Autosomal Dominant Hyper-IgE Syndrome) presents with these unique features.'),
    (v_topic_id, 'The mechanism in Job syndrome involves defective:', '["Th17 differentiation", "CD8 T-cell activation", "Complement fixation", "BTK signaling", "Class switching"]'::jsonb, 0, 'STAT3 mutations lead to failed Th17 differentiation and impaired neutrophil recruitment.'),
    (v_topic_id, 'Albinism, neuropathy, recurrent infections, and giant granules in neutrophils suggest:', '["Chediak-Higashi syndrome", "CGD", "LAD", "Wiskott-Aldrich", "Hyper-IgM"]'::jsonb, 0, 'Chediak-Higashi syndrome involves defective lysosomal trafficking (LYST gene).'),
    (v_topic_id, 'Chediak-Higashi syndrome is caused by defective:', '["Oxidative burst", "Lysosomal trafficking", "T-cell maturation", "Complement activation", "MHC II expression"]'::jsonb, 1, 'The LYST protein is essential for microtubule-mediated vesicle transport.'),
    (v_topic_id, 'Recurrent Neisseria infections strongly suggest deficiency of:', '["C3", "C5–C9", "IgA", "BTK", "CD40L"]'::jsonb, 1, 'Terminal complement components are required for the Membrane Attack Complex (MAC).'),
    (v_topic_id, 'The major function of C5–C9 is:', '["Opsonization", "B-cell activation", "Membrane attack complex formation", "Mast-cell activation", "Antigen presentation"]'::jsonb, 2, 'The MAC directly lyses gram-negative bacteria like Neisseria.'),
    (v_topic_id, 'C3 deficiency primarily impairs:', '["IgE production", "Opsonization", "T-cell maturation", "Class switching", "Mast-cell degranulation"]'::jsonb, 1, 'C3b is the primary opsonin of the complement system.'),
    (v_topic_id, 'Hereditary angioedema is due to deficiency of:', '["C3", "C1 esterase inhibitor", "C9", "Properdin", "Factor D"]'::jsonb, 1, 'C1 esterase inhibitor regulates the classical complement and kinin pathways.'),
    (v_topic_id, 'The mediator primarily responsible for hereditary angioedema swelling is:', '["Histamine", "Bradykinin", "IL-4", "TNF-alpha", "IFN-gamma"]'::jsonb, 1, 'Excess bradykinin causes increased vascular permeability and edema.'),
    (v_topic_id, 'Which immunoglobulin crosses the placenta?', '["IgA", "IgD", "IgE", "IgG", "IgM"]'::jsonb, 3, 'IgG is the only antibody class capable of placental transfer.'),
    (v_topic_id, 'Which immunoglobulin is the first produced in primary immune response?', '["IgA", "IgD", "IgE", "IgG", "IgM"]'::jsonb, 4, 'IgM is the initial antibody produced by B cells during a new infection.'),
    (v_topic_id, 'Which immunoglobulin is most important for mucosal immunity?', '["IgA", "IgD", "IgE", "IgG", "IgM"]'::jsonb, 0, 'Secretory IgA is the primary defender at mucosal surfaces.'),
    (v_topic_id, 'Which immunoglobulin is most strongly associated with helminth defense?', '["IgA", "IgD", "IgE", "IgG", "IgM"]'::jsonb, 2, 'IgE triggers eosinophil degranulation against parasites.'),
    (v_topic_id, 'Which immunoglobulin is a pentamer?', '["IgA", "IgD", "IgE", "IgG", "IgM"]'::jsonb, 4, 'Secreted IgM forms a large pentameric structure.'),
    (v_topic_id, 'Which antibody is found on naïve B cells together with IgM?', '["IgA", "IgD", "IgE", "IgG", "Secretory IgA"]'::jsonb, 1, 'Naive B cells express both IgM and IgD on their surface.'),
    (v_topic_id, 'The strongest activator of classical complement pathway is:', '["IgA", "IgD", "IgE", "IgG", "IgM"]'::jsonb, 4, 'IgM pentamers provide multiple binding sites for C1q.'),
    (v_topic_id, 'Which enzyme is essential for class switching and somatic hypermutation?', '["RAG", "BTK", "AID", "ADA", "MPO"]'::jsonb, 2, 'Activation-induced cytidine deaminase (AID) is required for both SHM and CSR.'),
    (v_topic_id, 'Affinity maturation primarily occurs in:', '["Bone marrow", "Thymus", "Germinal centers", "Red pulp", "Liver"]'::jsonb, 2, 'Germinal centers are the site of B-cell selection for high-affinity receptors.'),
    (v_topic_id, 'A newborn develops jaundice and anemia shortly after birth. The mother is Rh-negative and previously delivered an Rh-positive child. What is the mechanism?', '["Maternal IgM crossing placenta and lysing fetal RBCs", "Maternal IgG crossing placenta and causing hemolysis", "Fetal IgE-mediated mast-cell activation", "Maternal immune complex deposition in placenta", "Complement C5 deficiency"]'::jsonb, 1, 'Anti-Rh IgG crosses the placenta and causes extravascular hemolysis in the fetus.'),
    (v_topic_id, 'Prevention of hemolytic disease of the newborn is achieved by administration of:', '["Maternal anti-IgG antibodies", "Maternal anti-D immune globulin", "Fetal corticosteroids", "C1 esterase inhibitor", "IVIG to newborn only"]'::jsonb, 1, 'RhoGAM prevents maternal sensitization to fetal D-antigen.'),
    (v_topic_id, 'Which hypersensitivity type is hemolytic disease of the newborn?', '["Type I", "Type II", "Type III", "Type IV", "Type V"]'::jsonb, 1, 'It is a classic example of Type II (antibody-mediated) hypersensitivity.'),
    (v_topic_id, 'A patient with blistering skin disease has antibodies against desmogleins causing flaccid bullae. Diagnosis?', '["Bullous pemphigoid", "Pemphigus vulgaris", "Dermatitis herpetiformis", "Psoriasis", "Toxic epidermal necrolysis"]'::jsonb, 1, 'Pemphigus vulgaris involves Type II hypersensitivity against desmosomes.'),
    (v_topic_id, 'Bullous pemphigoid differs from pemphigus vulgaris because antibodies target:', '["Desmogleins", "Hemidesmosomes", "Type IV collagen", "dsDNA", "TSH receptor"]'::jsonb, 1, 'Bullous pemphigoid targets the basement membrane attachment (hemidesmosomes).'),
    (v_topic_id, 'A patient develops weakness that worsens with repeated muscle use. Antibodies target postsynaptic acetylcholine receptors. This is:', '["Type I hypersensitivity", "Type II hypersensitivity", "Type III hypersensitivity", "Type IV hypersensitivity", "Immune deficiency"]'::jsonb, 1, 'Myasthenia Gravis is a Type II hypersensitivity where antibodies block receptor function.'),
    (v_topic_id, 'Which hypersensitivity mechanism best explains rheumatic fever?', '["IgE mast-cell degranulation", "Antibody cross-reactivity with host tissue", "Immune complex nephritis", "Delayed T-cell activation", "Complement absence"]'::jsonb, 1, 'Molecular mimicry causes anti-streptococcal antibodies to attack cardiac tissue.'),
    (v_topic_id, 'A patient with farmer’s lung develops dyspnea after exposure to moldy hay. This is classically:', '["Type I", "Type II", "Type III", "Type IV", "Type V"]'::jsonb, 2, 'Hypersensitivity pneumonitis (HP) involves Type III immune complex deposition.'),
    (v_topic_id, 'The Arthus reaction is an example of:', '["Local type I hypersensitivity", "Local type III hypersensitivity", "Systemic type II hypersensitivity", "Type IV hypersensitivity", "Hyperacute rejection"]'::jsonb, 1, 'The Arthus reaction is a localized Type III hypersensitivity.'),
    (v_topic_id, 'A patient with lupus has deficiency of which complement components most strongly associated with disease risk?', '["C5–C9", "C1/C2/C4", "Properdin", "Factor D", "C8 only"]'::jsonb, 1, 'Early component deficiencies impair the clearance of immune complexes.'),
    (v_topic_id, 'Deficiency of C1 esterase inhibitor causes excess activation of:', '["Bradykinin pathway", "IgE production", "Th17 response", "NK-cell cytotoxicity", "B-cell maturation"]'::jsonb, 0, 'C1 inhibitor deficiency leads to unregulated bradykinin production.'),
    (v_topic_id, 'Which complement fragment is the strongest neutrophil chemotactic factor?', '["C3b", "C4b", "C5a", "C9", "C1q"]'::jsonb, 2, 'C5a is a potent recruiter of neutrophils.'),
    (v_topic_id, 'Which complement fragment is a major anaphylatoxin?', '["C3b", "C5a", "C9", "C1q", "Factor B"]'::jsonb, 1, 'C3a and C5a trigger mast cell degranulation.'),
    (v_topic_id, 'A child with recurrent respiratory infections has absent B cells and absent germinal centers. Most likely diagnosis?', '["CVID", "Bruton''s agammaglobulinemia", "Selective IgA deficiency", "Hyper-IgM syndrome", "SCID"]'::jsonb, 1, 'Bruton''s involves a maturational arrest at the pre-B stage.'),
    (v_topic_id, 'A patient has recurrent infections and low immunoglobulins despite normal B-cell count. Plasma cells are decreased. Diagnosis?', '["Bruton''s disease", "CVID", "Hyper-IgM syndrome", "IgA deficiency", "DiGeorge syndrome"]'::jsonb, 1, 'Common Variable Immunodeficiency (CVID) involves a failure of B cells to become plasma cells.'),
    (v_topic_id, 'Common variable immunodeficiency increases risk for:', '["Neisseria only", "Autoimmune disease and lymphoma", "Only fungal infections", "Severe albinism", "Delayed cord separation"]'::jsonb, 1, 'CVID is associated with chronic inflammation, autoimmunity, and malignancy.'),
    (v_topic_id, 'An infant with severe recurrent infections has X-linked SCID due to common gamma-chain mutation. Which cells are most reduced?', '["T cells", "Neutrophils", "RBCs", "Platelets", "Hepatocytes"]'::jsonb, 0, 'The common gamma chain (CD132) is critical for T-cell growth factor receptors (IL-7).'),
    (v_topic_id, 'The common gamma chain is shared by receptors for:', '["Only IL-1", "Multiple cytokines including IL-2 family", "Only IFN-gamma", "Only TNF-alpha", "Only IL-17"]'::jsonb, 1, 'It is part of the receptors for IL-2, 4, 7, 9, 15, and 21.'),
    (v_topic_id, 'Ataxia, telangiectasia, recurrent infections, and elevated AFP indicate:', '["Wiskott-Aldrich", "Ataxia-telangiectasia", "DiGeorge syndrome", "Job syndrome", "Hyper-IgM"]'::jsonb, 1, 'Ataxia-telangiectasia involves defective DNA repair and multi-system degeneration.'),
    (v_topic_id, 'The genetic defect in ataxia-telangiectasia is:', '["BTK mutation", "ATM mutation", "WAS mutation", "AID mutation", "CD40L mutation"]'::jsonb, 1, 'The ATM gene encodes a kinase involved in the double-strand break response.'),
    (v_topic_id, 'A patient with recurrent infections has absent MHC II expression. Which lymphocyte activation is most impaired?', '["CD8 T cells", "CD4 T cells", "NK cells", "Neutrophils", "Eosinophils"]'::jsonb, 1, 'MHC II is required to present exogenous antigen to CD4+ T helper cells.'),
    (v_topic_id, 'Loss of MHC I expression primarily impairs:', '["CD4 T cells", "CD8 T cells", "Plasma cells", "Mast cells", "Basophils"]'::jsonb, 1, 'MHC I is required to present endogenous antigen to CD8+ cytotoxic T cells.'),
    (v_topic_id, 'MHC I is normally expressed on:', '["APCs only", "All nucleated cells", "RBCs only", "Platelets only", "Only hepatocytes"]'::jsonb, 1, 'MHC I signals the health of nucleated cells to the immune system.'),
    (v_topic_id, 'MHC II is normally expressed on:', '["All nucleated cells", "RBCs only", "APCs such as dendritic cells, macrophages, B cells", "Neurons only", "Skeletal muscle only"]'::jsonb, 2, 'MHC II is restricted to professional antigen-presenting cells.'),
    (v_topic_id, 'Positive selection of T cells occurs in the:', '["Bone marrow", "Thymic cortex", "Thic medulla", "Germinal center", "Spleen"]'::jsonb, 1, 'Positive selection ensures T cells can recognize host MHC.'),
    (v_topic_id, 'Negative selection of T cells primarily occurs in the:', '["Thymic cortex", "Bone marrow", "Thymic medulla", "Liver", "Germinal center"]'::jsonb, 2, 'Negative selection (central tolerance) removes self-reactive T cells.'),
    (v_topic_id, 'Failure of AIRE gene function causes defective:', '["Peripheral B-cell maturation", "Central T-cell tolerance", "Complement synthesis", "NK-cell activation", "IgE production"]'::jsonb, 1, 'AIRE is required for the expression of tissue-specific antigens in the thymus.'),
    (v_topic_id, 'Which immunoglobulin best activates eosinophils against helminths?', '["IgA", "IgD", "IgE", "IgG", "IgM"]'::jsonb, 2, 'IgE binds to parasites, and eosinophils bind the Fc portion of IgE to degranulate.'),
    (v_topic_id, 'The cytokine most important for eosinophil activation is:', '["IL-1", "IL-2", "IL-5", "IFN-gamma", "TGF-beta"]'::jsonb, 2, 'IL-5 is the major driver of eosinophil growth and activation.'),
    (v_topic_id, 'Secretory IgA is especially resistant to degradation because of:', '["Complement coating", "Secretory component", "Pentameric structure", "Fc receptor binding", "MHC II interaction"]'::jsonb, 1, 'The secretory component protects IgA from luminal proteases.'),
    (v_topic_id, 'A positive anti-HAV IgM most strongly suggests:', '["Past resolved infection only", "Acute recent infection", "Chronic latent infection", "Vaccination only", "Autoimmune hepatitis"]'::jsonb, 1, 'IgM is the marker of the current or acute phase of infection.'),
    (v_topic_id, 'The first antibody produced during primary immune response is:', '["IgA", "IgD", "IgE", "IgG", "IgM"]'::jsonb, 4, 'IgM is the initial isotype secreted before class switching occurs.'),
    (v_topic_id, 'Naïve mature B cells express:', '["IgA and IgE", "IgM and IgD", "IgG and IgA", "IgE and IgG", "IgM only"]'::jsonb, 1, 'Naive B cells have not yet undergone isotype switching but express D and M.'),
    (v_topic_id, 'Class switching changes:', '["Antigen specificity", "Heavy-chain constant region", "Light-chain variable region only", "T-cell receptor recognition", "MHC restriction"]'::jsonb, 1, 'Isotype switching changes the effector function (Fc) without changing specificity.'),
    (v_topic_id, 'Which enzyme is required for both class switching and somatic hypermutation?', '["BTK", "RAG", "AID", "MPO", "ADA"]'::jsonb, 2, 'AID deaminates cytosine to uracil in DNA to initiate these processes.'),
    (v_topic_id, 'Somatic hypermutation primarily improves:', '["Antibody quantity", "Antibody affinity", "Complement activation only", "T-cell tolerance", "Mast-cell degranulation"]'::jsonb, 1, 'Point mutations in the variable region lead to higher affinity binding.'),
    (v_topic_id, 'Affinity maturation occurs mainly in:', '["Bone marrow", "Germinal centers", "Thymus", "Liver", "Red pulp only"]'::jsonb, 1, 'B cells with the highest affinity are selected for survival in germinal centers.'),
    (v_topic_id, 'Hyperacute transplant rejection is caused by:', '["Preformed recipient antibodies", "Delayed T-cell activation", "Chronic fibrosis only", "Immune complex deposition", "NK-cell deficiency"]'::jsonb, 0, 'Immediate rejection is due to pre-existing antibodies against donor antigens (e.g., ABO).'),
    (v_topic_id, 'Acute cellular rejection is mediated primarily by:', '["Mast cells", "T lymphocytes", "IgE", "Complement only", "Neutrophils only"]'::jsonb, 1, 'Acute rejection is a Type IV-like response where T cells attack the graft.'),
    (v_topic_id, 'Chronic rejection is characterized by:', '["Immediate thrombosis", "Obliterative intimal fibrosis", "Eosinophilic infiltrates", "Linear IgG staining", "Giant granules"]'::jsonb, 1, 'Vascular injury leads to gradual narrowing of the graft vessels.'),
    (v_topic_id, 'Bone marrow transplant causing rash, jaundice, and diarrhea suggests:', '["Hyperacute rejection", "GVHD", "Serum sickness", "Acute hemolysis", "SCID"]'::jsonb, 1, 'Graft-versus-host disease occurs when donor T cells attack the recipient.'),
    (v_topic_id, 'The tissues classically involved in GVHD are:', '["Brain, bone, kidney", "Skin, liver, GI tract", "Heart, kidney, pancreas only", "Eye and thymus only", "Thyroid and adrenal only"]'::jsonb, 1, 'Skin rash, jaundice (liver), and diarrhea (GI) are the characteristic triad.'),
    (v_topic_id, 'Rituximab therapy depletes:', '["Plasma cells", "Mature B cells", "T helper cells", "NK cells", "Neutrophils"]'::jsonb, 1, 'Rituximab targets CD20, which is expressed on B cells but not plasma cells.'),
    (v_topic_id, 'Plasma cells are relatively spared by rituximab because they:', '["Are not derived from B cells", "Lack CD20 expression", "Express only IgM", "Are thymic cells", "Require complement"]'::jsonb, 1, 'Plasma cells downregulate CD20 during differentiation.'),
    (v_topic_id, 'Which cytokine is most associated with Th2 differentiation?', '["IL-4", "IL-12", "IFN-gamma", "IL-17", "IL-2"]'::jsonb, 0, 'IL-4 promotes Th2 development, while IL-12 promotes Th1.'),
    (v_topic_id, 'Which cytokine drives Th1 differentiation?', '["IL-4", "IL-5", "IL-12", "IL-17", "IL-10"]'::jsonb, 2, 'IL-12 from macrophages and DCs drives the Th1 response.'),
    (v_topic_id, 'Which cytokine is most associated with neutrophil recruitment?', '["IL-17", "IL-4", "IL-5", "IL-10", "IFN-alpha"]'::jsonb, 0, 'Th17 cells produce IL-17 to recruit neutrophils to sites of infection.'),
    (v_topic_id, 'Regulatory T cells primarily produce:', '["IL-2 and IFN-gamma", "IL-10 and TGF-beta", "IL-4 and IL-5", "IL-17 and IL-6", "TNF-alpha and IL-1"]'::jsonb, 1, 'These anti-inflammatory cytokines suppress the immune response.'),
    (v_topic_id, 'The strongest immediate treatment for anaphylaxis is:', '["Oral steroids", "Diphenhydramine only", "Intramuscular epinephrine", "Inhaled steroids", "Montelukast"]'::jsonb, 2, 'Epinephrine provides both alpha-1 and beta-2 adrenergic stimulation.'),
    (v_topic_id, 'A booster vaccine produces a stronger response mainly because of:', '["Complement memory", "Memory B cells with affinity-matured antibodies", "Persistent IgM only", "Neutrophil activation", "Mast-cell sensitization"]'::jsonb, 1, 'Memory cells respond faster and produce higher affinity IgG.'),
    (v_topic_id, 'A patient with recurrent sinopulmonary infections has normal B-cell count but low IgG, low IgA, and low IgM. Plasma cells are decreased. Which diagnosis is most likely?', '["Bruton''s agammaglobulinemia", "Selective IgA deficiency", "Common variable immunodeficiency", "Hyper-IgM syndrome", "DiGeorge syndrome"]'::jsonb, 2, 'CVID presents with pan-hypogammaglobulinemia but normal B cell numbers.'),
