-- Migration: 150 High-Yield Immunology MCQs
-- Category: USMLE Step 1
-- Date: 2026-04-23

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- 1. Get Topic ID for Immunology
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'immunology' LIMIT 1;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic "immunology" not found. Please ensure the topic migration has been run.';
    END IF;

    -- 2. Clear existing MCQs for this topic to ensure clean migration
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- 3. Ingest 150 High-Yield MCQs

END $$;

COMMIT;
